begin;
alter table public.studio_project_stages add column if not exists is_archived boolean not null default false;
alter table public.studio_project_stages add column if not exists archived_at timestamptz;
alter table public.studio_project_stages add column if not exists archived_by uuid references auth.users(id);
create table if not exists public.studio_project_stage_files(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid not null references public.studio_projects(id),stage_id uuid not null references public.studio_project_stages(id),file_id uuid not null references public.studio_project_files(id),version_id uuid references public.studio_project_file_versions(id),attachment_role text not null default 'other' check(attachment_role in('approval_document','drawing','report','submission','other')),is_customer_visible boolean not null default false,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),archived_at timestamptz,archived_by uuid references auth.users(id));
create unique index if not exists studio_stage_files_active_uq on public.studio_project_stage_files(stage_id,file_id,coalesce(version_id,'00000000-0000-0000-0000-000000000000'::uuid)) where archived_at is null;
create index if not exists studio_stage_files_scope_idx on public.studio_project_stage_files(organization_id,project_id,stage_id) where archived_at is null;
create table if not exists public.studio_notification_attachments(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),notification_id uuid not null references public.studio_notifications(id),stage_file_id uuid references public.studio_project_stage_files(id),file_id uuid not null references public.studio_project_files(id),version_id uuid references public.studio_project_file_versions(id),status text not null default 'queued' check(status in('queued','sent','failed','cancelled')),provider_media_id text,provider_message_id text,safe_error_code text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists studio_notification_attachments_notification_idx on public.studio_notification_attachments(notification_id,created_at);
create or replace function public.studio_validate_stage_file_scope() returns trigger language plpgsql set search_path=public as $$ declare s record;f record;v record;begin select organization_id,project_id into s from public.studio_project_stages where id=new.stage_id;select organization_id,project_id,extension into f from public.studio_project_files where id=new.file_id;if s is null or f is null or s.organization_id<>new.organization_id or s.project_id<>new.project_id or f.organization_id<>new.organization_id or f.project_id<>new.project_id or lower(f.extension) not in('pdf','dwg') then raise exception 'stage_file_scope_invalid' using errcode='23514';end if;if new.version_id is not null then select file_id,organization_id,project_id into v from public.studio_project_file_versions where id=new.version_id;if v is null or v.file_id<>new.file_id or v.organization_id<>new.organization_id or v.project_id<>new.project_id then raise exception 'stage_version_scope_invalid' using errcode='23514';end if;end if;return new;end $$;
drop trigger if exists studio_validate_stage_file_scope_trigger on public.studio_project_stage_files;create trigger studio_validate_stage_file_scope_trigger before insert or update on public.studio_project_stage_files for each row execute function public.studio_validate_stage_file_scope();
create or replace function public.studio_reorder_project_stage(target_stage uuid,direction integer) returns void language plpgsql security invoker set search_path=public as $$ declare a record;b record;begin if direction not in(-1,1) then raise exception 'invalid_direction' using errcode='22023';end if;select * into a from public.studio_project_stages where id=target_stage for update;if a is null or not public.studio_has_organization_role(a.organization_id,array['owner']) then raise exception 'stage_forbidden' using errcode='42501';end if;if direction=-1 then select * into b from public.studio_project_stages where project_id=a.project_id and is_active and not is_archived and sort_order<a.sort_order order by sort_order desc limit 1 for update;else select * into b from public.studio_project_stages where project_id=a.project_id and is_active and not is_archived and sort_order>a.sort_order order by sort_order limit 1 for update;end if;if b is null then return;end if;update public.studio_project_stages set sort_order=10000 where id=a.id;update public.studio_project_stages set sort_order=a.sort_order where id=b.id;update public.studio_project_stages set sort_order=b.sort_order where id=a.id;end $$;
alter table public.studio_project_stage_files enable row level security;alter table public.studio_notification_attachments enable row level security;
create policy studio_stage_files_select on public.studio_project_stage_files for select to authenticated using(public.studio_is_organization_member(organization_id));create policy studio_stage_files_owner_insert on public.studio_project_stage_files for insert to authenticated with check(created_by=auth.uid() and public.studio_has_organization_role(organization_id,array['owner']));create policy studio_stage_files_owner_update on public.studio_project_stage_files for update to authenticated using(public.studio_has_organization_role(organization_id,array['owner'])) with check(public.studio_has_organization_role(organization_id,array['owner']));create policy studio_notification_attachments_select on public.studio_notification_attachments for select to authenticated using(public.studio_is_organization_member(organization_id));
grant select,insert,update on public.studio_project_stage_files to authenticated;grant select on public.studio_notification_attachments to authenticated;grant execute on function public.studio_reorder_project_stage(uuid,integer) to authenticated;revoke delete on public.studio_project_stage_files,public.studio_notification_attachments from anon,authenticated;create table if not exists public.studio_project_stage_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),project_id uuid not null references public.studio_projects(id),stage_id uuid not null references public.studio_project_stages(id),event_type text not null,title text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create index if not exists studio_stage_events_timeline_idx on public.studio_project_stage_events(stage_id,created_at desc);
alter table public.studio_project_stage_events enable row level security;
create policy studio_stage_events_select on public.studio_project_stage_events for select to authenticated using(public.studio_is_organization_member(organization_id));
create policy studio_stage_events_owner_insert on public.studio_project_stage_events for insert to authenticated with check(public.studio_has_organization_role(organization_id,array['owner']));
create policy studio_notification_attachments_owner_insert on public.studio_notification_attachments for insert to authenticated with check(public.studio_has_organization_role(organization_id,array['owner']));
create policy studio_notification_attachments_owner_update on public.studio_notification_attachments for update to authenticated using(public.studio_has_organization_role(organization_id,array['owner'])) with check(public.studio_has_organization_role(organization_id,array['owner']));
grant select,insert on public.studio_project_stage_events to authenticated;grant insert,update on public.studio_notification_attachments to authenticated;revoke delete on public.studio_project_stage_events from anon,authenticated;
notify pgrst,'reload schema';commit;
